14	func drainAudit(t *testing.T, s *Store, org, kind, subject string) []AuditRecord {
15		t.Helper()
16		page, err := s.AuditQuery(org, 1, 4, kind, subject)
17		if err != nil {
18			t.Fatalf("AuditQuery: %v", err)
