477	// OfflineRecheckResult is the outcome of rechecking one decision record
478	// entirely from exported audit material. It carries the decision recorded
479	// at the time, the decision recomputed from the export, and whether every
480	// field of the two decisions agrees.
481	type OfflineRecheckResult struct {
482		// Seq is the rechecked record's organization-local sequence.
483		Seq int
484		// Original is the decision stored in the target audit record.
485		Original Decision
486		// Recomputed is the decision rebuilt from the verified export.
487		Recomputed Decision
488		// Match reports whether Original and Recomputed agree on every field.
489		Match bool
490	}
491	
492	// RecheckDecisionOffline re-evaluates the decision at seq using only the
493	// organization name, a complete export (records starting at sequence 1)
494	// and the checkpoint saved alongside it. No Store is created or restored;
495	// the exported material is never modified and no audit record is appended.
496	//
497	// The whole export is chain-verified first, including records after the
498	// target: any rewritten field, deleted middle or tail record, swapped
499	// order, foreign-organization record, or checkpoint mismatch fails the
500	// recheck without producing a result. A legal prefix export with its
501	// matching checkpoint is accepted; subject-filtered pages and fragments
502	// missing the beginning are not, because VerifyAudit requires a gapless
503	// chain starting at sequence 1. An empty export with its genesis
504	// checkpoint verifies but contains no decision to recheck.
505	//
506	// The recomputation uses the request saved in the target record and the
507	// policy version that decision actually used. That version's full policy
508	// set must be carried by a policy-change record preceding the target in
509	// the export; a version missing from the export, or appearing only after
510	// the target, is an error — a newer version is never substituted. Later
511	// publishes, rollbacks, or export-scope expansion cannot change the
512	// result. Rollback-produced versions use the full content carried by
513	// their change record and the result notes the new version number.
514	//
515	// Version 0 restores the original envelope rejections (missing fields,
516	// organization mismatch, invalid scope, disabled subject); an otherwise
517	// valid request restores the no-published-version denial, still at
518	// version 0. Policy judgment keeps default denial and deny-overrides.
519	//
520	// A chain that verifies but whose recomputed decision differs returns
521	// both complete decisions with Match=false; the original conclusion is
522	// never reported as the recomputed one. Returned data is detached from
523	// the input records.
524	func RecheckDecisionOffline(org string, records []AuditRecord, cp Checkpoint, seq int) (*OfflineRecheckResult, error) {
525		if org == "" {
526			return nil, ErrMissingOrganization
527		}
528		if seq < 1 {
529			return nil, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
530		}
531		// Verify the entire export before touching the target; corruption
532		// past the target is not ignored.
533		if err := VerifyAudit(org, records, cp); err != nil {
534			return nil, err
535		}
536		if seq > len(records) {
537			return nil, fmt.Errorf("%w: organization %q has no audit sequence %d", ErrAuditNotFound, org, seq)
538		}
539		rec := records[seq-1]
540		if rec.Kind != AuditDecision || rec.Decision == nil {
541			return nil, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
542		}
543	
544		original := rec.Decision.Decision
545		req := rec.Decision.Request
546		var recomputed Decision
547		if original.Version == 0 {
548			// No published version was evaluated: restore the envelope
549			// rejection when one applies, otherwise the unpublished denial.
550			if d, ok := checkRequest(org, req); !ok {
551				recomputed = d
552			} else {
553				recomputed = Decision{Allowed: false, Reason: "organization has no published version"}
554			}
555		} else {
556			// The version's full policy set must be recorded before the
557			// target; a change record appearing only after it cannot be the
558			// basis of the original decision.
559			policies, ok := policiesForVersionBefore(records, seq-1, original.Version)
560			if !ok {
561				return nil, fmt.Errorf("%w: decision at sequence %d used version %d, whose full policy set is not recorded before it in the export",
562					ErrVersionNotFound, seq, original.Version)
563			}
564			recomputed = evaluate(req, policies, original.Version)
565		}
566	
567		return &OfflineRecheckResult{
568			Seq:        seq,
569			Original:   cloneDecisionValue(original),
570			Recomputed: cloneDecisionValue(recomputed),
571			Match:      decisionsEqual(original, recomputed),
572		}, nil
573	}
574	
575	// policiesForVersionBefore scans records[0:before] for a policy-change
576	// record establishing version and returns a detached copy of its full
577	// policy set. The version must precede the decision that used it.
578	func policiesForVersionBefore(records []AuditRecord, before, version int) ([]Policy, bool) {
579		for i := 0; i < before; i++ {
580			r := records[i]
581			if r.Kind == AuditPolicyChange && r.Change != nil && r.Change.Version == version {
582				return clonePolicies(r.Change.Policies), true
583			}
584		}
585		return nil, false
586	}
587	
588	// decisionsEqual compares every decision field. Matched lists are
589	// compared element by element in their deterministic order; a nil list
590	// and an empty list are the same empty result.
591	func decisionsEqual(a, b Decision) bool {
592		if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
593			return false
594		}
595		if len(a.Matched) != len(b.Matched) {
596			return false
597		}
598		for i := range a.Matched {
599			if a.Matched[i] != b.Matched[i] {
600				return false
601			}
602		}
603		return true
604	}
